import React from 'react';

import PohAlert from '@ui-kit/Alert';
import PohList from '@ui-kit/List';
import PohLoader from '@ui-kit/Loader';

import { getFoodActs } from '../../../Hiking/@services/food.service';
import { IBaseFoodAct } from '../../../Hiking/@types/hiking.baseTypes';

interface IFoodActSelectModalProps {
  onSelect: (selected: IBaseFoodAct) => void;
}

const FoodActSelectModal: React.FC<IFoodActSelectModalProps> = ({ onSelect }) => {
  const [data, setData] = React.useState<IBaseFoodAct[]>([]);
  const [isLoading, setIsLoading] = React.useState(false);
  const [error, setError] = React.useState('');

  React.useEffect(() => {
    async function fetch() {
      try {
        setIsLoading(true);
        const res = await getFoodActs();
        setData(res);
      } catch (e) {
        setError((e as Error).message);
      } finally {
        setIsLoading(false);
      }
    }
    fetch();
  }, []);

  if (isLoading) {
    return <PohLoader />;
  }

  if (error.length) {
    return <PohAlert>{error}</PohAlert>;
  }

  return (
    <PohList
      data={data.map((fa) => ({
        key: fa.id,
        action: true,
        content: fa.name,
        onClick: () => onSelect(fa),
      }))}
    />
  );
};

export default FoodActSelectModal;
