import { showModal } from '@ui-kit/Modal/modalsHelper';

import RouteObjectSelectModal, { IRouteObjectSelectModalProps } from './index';
import { IRouteObject } from '../@types/routes.types';

export const selectRouteObjectAsync = (
  id_route: number,
  title = 'Объект маршрута',
  props?: Partial<IRouteObjectSelectModalProps>,
): Promise<IRouteObject> => {
  return new Promise<IRouteObject>((res, rej) => {
    showModal({
      onClose: rej,
      title,
      children: (close: () => void) => (
        <RouteObjectSelectModal
          {...props}
          id_route={id_route}
          onSelect={(v) => {
            res(v);
            close();
          }}
        />
      ),
    });
  });
};
